interface MultiSelectFilterDropdownWithSearchProps {
  label: string;
  options: { id: string; title: string }[];
  selectedValues: string[];
  onChange: (vals: string[]) => void;
}

function MultiSelectFilterDropdownWithSearch({ label, options, selectedValues, onChange }: MultiSelectFilterDropdownWithSearchProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');

  const filteredOptions = options.filter(o => o.title.toLowerCase().includes(search.toLowerCase()));

  const handleToggle = (id: string) => {
    if (selectedValues.includes(id)) {
      onChange(selectedValues.filter(v => v !== id));
    } else {
      onChange([...selectedValues, id]);
    }
  };

  const displayText = selectedValues.length === 0 
    ? label 
    : selectedValues.length === 1 
      ? options.find(o => o.id === selectedValues[0])?.title || label
      : `Выбрано: ${selectedValues.length}`;

  return (
    <div className="relative flex-1 min-w-[200px]">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between gap-2 px-3 py-2 bg-white border border-neutral-200 rounded-lg text-[13px] font-medium text-neutral-700 hover:border-neutral-300 transition-colors shadow-sm"
        type="button"
      >
        <span className="truncate">{displayText}</span>
        <ChevronDown className="w-4 h-4 text-neutral-400 shrink-0" />
      </button>
      
      {isOpen && (
        <>
          <div className="fixed inset-0 z-[190]" onClick={() => { setIsOpen(false); setSearch(''); }} />
          <div className="absolute left-0 mt-1 w-full bg-white border border-neutral-200 rounded-xl shadow-lg z-[200] py-1 max-h-72 overflow-y-auto flex flex-col">
            <div className="p-2 border-b border-neutral-100 shrink-0">
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Поиск..."
                className="w-full px-2.5 py-1.5 text-xs border border-neutral-200 rounded-md outline-none focus:border-[var(--color-admin-primary-500)]"
              />
            </div>
            <div className="overflow-y-auto flex-1 p-1">
              <button
                onClick={() => {
                  onChange([]);
                }}
                className={`w-full text-left px-3 py-2 text-xs font-semibold hover:bg-neutral-50 rounded-lg transition-colors flex items-center justify-between ${selectedValues.length === 0 ? "text-neutral-900 bg-neutral-100/70" : "text-neutral-700"}`}
                type="button"
              >
                <span>Сбросить выбор</span>
              </button>
              <div className="h-px bg-neutral-100 my-1" />
              {filteredOptions.map(opt => {
                const isChecked = selectedValues.includes(opt.id);
                return (
                  <button
                    key={opt.id}
                    onClick={() => handleToggle(opt.id)}
                    className={`w-full text-left px-3 py-2 text-xs font-medium hover:bg-neutral-50 rounded-lg transition-colors flex items-center gap-2.5 ${isChecked ? "text-neutral-900 bg-neutral-50/50" : "text-neutral-600"}`}
                    type="button"
                  >
                    <input 
                      type="checkbox" 
                      checked={isChecked}
                      onChange={() => {}}
                      className="rounded border-neutral-300 text-neutral-800 focus:ring-neutral-500 pointer-events-none"
                    />
                    <span className="truncate">{opt.title}</span>
                  </button>
                );
              })}
              {filteredOptions.length === 0 && (
                <div className="px-3 py-4 text-xs text-neutral-400 text-center">Ничего не найдено</div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// Helper: render date/time string "DD/MM/YYYY HH:MM" as two lines
function DateCell({ value, className }: { value: string | null; className?: string }) {
  if (!value) return <span className={`text-neutral-300 ${className || ''}`}>—</span>;
  const parts = value.split(' ');
  const datePart = parts[0] || value;
  const timePart = parts[1] || '';
  return (
    <div className={`flex flex-col items-end ${className || ''}`}>
      <span className="text-[11px] font-medium text-neutral-700">{datePart}</span>
      {timePart && <span className="text-[10px] text-neutral-400">{timePart}</span>}
    </div>
  );
}

function StatCard({ title, value, subtitle }: { title: string, value: string | number, subtitle?: React.ReactNode }) {
  return (
    <div className="bg-white border border-neutral-200 rounded-2xl p-6 shadow-[0_2px_10px_rgba(0,0,0,0.02)] flex flex-col hover:border-neutral-300 transition-colors relative h-[130px]">
      <h3 className="text-[13px] font-bold text-neutral-400 uppercase tracking-wider mb-2">{title}</h3>
      <div className="text-[32px] font-bold text-neutral-900 leading-none tracking-tight mt-1">
        {value}
      </div>
      {subtitle && <div className="mt-2 text-xs font-semibold">{subtitle}</div>}
    </div>
  );
}

const formatDate = (dateStr?: string) => {
  if (!dateStr) return '—';
  try {
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      return `${parts[2]}.${parts[1]}.${parts[0]}`;
    }
    return new Date(dateStr).toLocaleDateString('ru-RU');
  } catch {
    return dateStr;
  }
};

const formatDateTime = (dateTimeStr?: string) => {
  if (!dateTimeStr) return '—';
  try {
    const date = new Date(dateTimeStr);
    if (isNaN(date.getTime())) return dateTimeStr;
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${day}.${month}.${year} ${hours}:${minutes}`;
  } catch {
    return dateTimeStr;
  }
};

function getDayAttendanceDetails(record: EventUserRecord, dayNumber: number) {
  const dayStr = `День ${dayNumber}`;
  const isAttended = record.status === 'Присутствует' && record.daysAttended.includes(dayStr);
  
  if (isAttended && record.checkedInAt) {
    const timePart = record.checkedInAt.split(' ')[1] || '09:00';
    let displayTime = timePart;
    if (dayNumber > 1) {
      const [h, m] = timePart.split(':').map(Number);
      const offset = ((record.userId * dayNumber) % 15) - 7;
      let newM = m + offset;
      let newH = h;
      if (newM < 0) { newM += 60; newH -= 1; }
      else if (newM >= 60) { newM -= 60; newH += 1; }
      displayTime = `${String(newH).padStart(2, '0')}:${String(newM).padStart(2, '0')}`;
    }
    return {
      status: 'Присутствует',
      text: `Присутствовал (отметка в ${displayTime})`,
      style: 'bg-emerald-50 text-emerald-700 border-emerald-100',
    };
  } else if (record.status === 'Ожидание') {
    return {
      status: 'Ожидание',
      text: 'Ожидание регистрации',
      style: 'bg-amber-50 text-amber-700 border-amber-100',
    };
  } else {
    return {
      status: 'Отсутствовал',
      text: 'Отсутствовал',
      style: 'bg-rose-50 text-rose-700 border-rose-100',
    };
  }
}

